from collections import Counter
total_counts = Counter()
for row in test_input:
    for val in row:
        if val > 0:
            total_counts[val] += 1

print("Total counts from input:", total_counts)

# Left vs right for each color
def count_sides(grid, color):
    left, right = 0, 0
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == color:
                if c < 5:
                    left += 1
                else:
                    right += 1
    return left, right

print(f"Color 2 left/right: {count_sides(test_input, 2)}")
print(f"Color 3 left/right: {count_sides(test_input, 3)}")
